describe('Right-click context menu on table row', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.get('table tbody tr').should('have.length.greaterThan', 0);
  });

  it('should display context menu when right-clicking a table row', () => {
    cy.get('table tbody tr').first().rightclick();

    cy.get('[role="menu"]').should('be.visible');
    cy.get('[role="menuitem"]').should('have.length.greaterThan', 0);
  });

  it('should display correct menu items in context menu', () => {
    cy.get('table tbody tr').first().rightclick();

    cy.get('[role="menu"]').should('be.visible');
    cy.get('[role="menuitem"]').each(($item) => {
      cy.wrap($item).should('be.visible');
    });
  });

  it('should close context menu when clicking elsewhere', () => {
    cy.get('table tbody tr').first().rightclick();
    cy.get('[role="menu"]').should('be.visible');

    cy.get('body').click(0, 0);
    cy.get('[role="menu"]').should('not.be.visible');
  });

  it('should execute action when clicking menu item', () => {
    cy.get('table tbody tr').first().rightclick();
    cy.get('[role="menu"]').should('be.visible');

    cy.get('[role="menuitem"]').first().click();
    cy.get('[role="menu"]').should('not.be.visible');
  });

  it('should handle right-click on different rows independently', () => {
    cy.get('table tbody tr').eq(0).rightclick();
    cy.get('[role="menu"]').should('be.visible');

    cy.get('table tbody tr').eq(1).rightclick();
    cy.get('[role="menu"]').should('be.visible');
  });

  it('should not display context menu on right-click of disabled row', () => {
    cy.get('table tbody tr[aria-disabled="true"]').first().rightclick();
    cy.get('[role="menu"]').should('not.exist');
  });

  it('should prevent default browser context menu', () => {
    cy.get('table tbody tr').first().rightclick();
    cy.get('[role="menu"]').should('be.visible');

    cy.window().then((win) => {
      cy.spy(win, 'addEventListener');
    });
  });

  it('should display context menu with keyboard accessibility', () => {
    cy.get('table tbody tr').first().focus();
    cy.get('table tbody tr').first().trigger('contextmenu');

    cy.get('[role="menu"]').should('be.visible');
    cy.get('[role="menuitem"]').first().should('have.focus');
  });

  it('should handle rapid successive right-clicks', () => {
    cy.get('table tbody tr').first().rightclick();
    cy.get('[role="menu"]').should('be.visible');

    cy.get('table tbody tr').first().rightclick();
    cy.get('[role="menu"]').should('be.visible');
    cy.get('[role="menuitem"]').should('have.length.greaterThan', 0);
  });
});
